const cases={
compass:{title:'Claude CompassLoop',kicker:'AI PRODUCT STRATEGY / INDEPENDENT FELLOWSHIP CONCEPT',intro:'Making the decision to delegate more understandable. A concept that helps users inspect an agent’s intended approach before committing time, tokens, and trust.',prototype:'https://compass-claude.lovable.app/',deck:'https://assets.nextleap.app/submissions/NL_Claude_Compass-899031f3-0995-4326-a440-722cf0259272.pdf',evidence:'Source: Sameer’s supplied 10-page CompassLoop deck and linked prototype. Research sample: 75 survey responses and 7 interviews. Independent concept; not an Anthropic engagement. Market estimates, financial models, forecasts, and rollout figures in the original deck are not achieved results.',panels:[
{label:'Problem',title:'The decision before the run.',body:'<p>Advanced capabilities introduce a different decision: should I use a prompt, a project, a workflow, or an agent? The research in my deck explores how uncertainty about the approach, cost, and consequences can discourage users from delegating.</p><div class="case-callout">Core hypothesis: making the plan visible before execution could help users make more informed delegation decisions.</div><p>The project includes 75 survey responses, seven user interviews, and secondary research. These are findings from the study sample; they do not establish population-wide behavior or prove adoption uplift.</p><ul><li><strong>Primary segment:</strong> frequent users who over-plan or rewrite prompts before complex tasks.</li><li><strong>Adjacent segment:</strong> cautious explorers who need a clearer explanation of advanced capabilities.</li><li><strong>Product question:</strong> can a pre-run decision layer reduce uncertainty without creating more friction?</li></ul>'},
{label:'Decisions',title:'Preview first. Broader controls later.',body:'<p>I compared three directions: CompassLoop, which reveals the intended plan; Rewind, which explores rollback; and Trust Tiers, which sets reusable rules.</p><ul><li><strong>CompassLoop:</strong> make the approach, estimated resources, and risks inspectable before the user commits.</li><li><strong>Rewind:</strong> valuable for recovery, but expensive to support and incomplete for external actions that cannot simply be undone.</li><li><strong>Trust Tiers:</strong> potentially useful for repeat users, but rules are easier to configure when the underlying plan is understandable.</li></ul><div class="case-callout">The trade-off: prioritize decision clarity before expanding into recovery infrastructure or persistent permission rules.</div><p>The deck’s prioritization scores express my assumptions. They are a way to compare directions, not validated estimates of engineering effort.</p>'},
{label:'Experience',title:'Mirror → Preview → Run → Learn.',body:'<ul><li><strong>Mirror:</strong> surface the interpreted task and assumptions so users can correct intent before execution.</li><li><strong>Preview:</strong> compare Quick, Standard, and Deep approaches with proposed steps and resource estimates.</li><li><strong>Run:</strong> keep the approved plan visible alongside execution.</li><li><strong>Learn:</strong> gather explicit feedback and explore reusable workflows.</li></ul><p>The linked prototype makes the proposed interaction tangible. Interface estimates and sample activity should be read as prototype behavior, not proof of calibrated prediction or production execution guarantees.</p><div class="case-callout">Design principle: give users enough information to choose, while preserving their ability to edit, simplify, or stop.</div>'},
{label:'Validation',title:'A trust hypothesis needs a real test.',body:'<p>The deck proposes a Confident Decision Rate and supporting measures. Its projections are targets and models, not observed product outcomes.</p><p>A stronger validation plan would compare preview-assisted and existing task flows using representative tasks and clear success criteria.</p><ul><li><strong>Decision quality:</strong> task completion and capability choice, alongside user-reported understanding.</li><li><strong>Prediction quality:</strong> compare resource estimates with actual usage; test whether confidence estimates are calibrated.</li><li><strong>Guardrails:</strong> preview latency, planning overhead, unintended actions, and user overrides.</li><li><strong>Business hypothesis:</strong> improved decision clarity may support repeat use. Retention and willingness to pay still need testing.</li></ul><div class="case-callout">Next question: does preview create informed confidence, or simply make an uncertain system look more certain?</div>'}
]},
attune:{title:'Attune',kicker:'DIGITAL WELLBEING / INDEPENDENT RESEARCH + PROTOTYPE',intro:'Understanding before control. A concept for helping people notice their scrolling patterns, reflect without judgment, and choose small changes for themselves.',prototype:'https://attunedigitalwellbeing.lovable.app/',deck:'https://assets.nextleap.app/submissions/NLDigitalWellbeingAttune-90ea43f3-eb22-4f63-a434-d28659a6b726.pdf',evidence:'Source: Sameer’s supplied 10-page Attune deck and linked prototype. The project includes survey research and seven user interviews. Research findings are sample-specific; forecasts and success targets are not launch results.',panels:[
{label:'Problem',title:'When another timer misses the point.',body:'<p>Attune explores late-night scrolling among Android users in India who recognize their screen-time problem but repeatedly bypass restrictions. The deck frames this as a question about emotional context, autonomy, and the gap between intention and action.</p><div class="case-callout">Research direction: understand the need behind the behavior before proposing another restriction.</div><p>The target persona is an “Anxious Night-Scroller”: an urban professional who uses the phone to decompress but feels that a brief break turns into an unintended late night.</p><p>The research includes surveys and seven interviews. The findings describe this research sample and are not representative estimates for all Indian smartphone users.</p>'},
{label:'Decisions',title:'Insight should lead to a choice.',body:'<p>I explored three directions: a chat-based behavior coach, a habit-versus-emotion classifier, and Attune’s combination of reflection and voluntary action.</p><ul><li><strong>Behavior coach:</strong> can explain patterns, but depends on the user choosing to start a conversation.</li><li><strong>Classifier:</strong> could make patterns clearer, but risks becoming another dashboard.</li><li><strong>Attune:</strong> pairs a short behavioral story with an optional, self-chosen experiment.</li></ul><div class="case-callout">The product choice: connect reflection to action while keeping the user in control.</div><p>The prioritization in the deck is an assumption-based comparison. The preferred direction still needs usability and behavioral validation.</p>'},
{label:'Experience',title:'Reflect. Choose a shift. Check back.',body:'<ul><li><strong>Replay the week:</strong> turn usage patterns into a short narrative rather than an endless stream of statistics.</li><li><strong>Check the interpretation:</strong> ask whether an insight feels accurate instead of asserting an emotional diagnosis.</li><li><strong>Choose one small shift:</strong> offer an experiment the user can accept, adjust, or decline.</li><li><strong>Return with context:</strong> explore progress across weeks without framing a missed target as personal failure.</li></ul><p>The prototype illustrates this interaction model. The phone artwork on the portfolio is a visual interpretation of the concept, not a screenshot or a measured usage chart.</p><div class="case-callout">User trust depends on being able to disagree with the system.</div>'},
{label:'Validation',title:'Understanding is a start, not the outcome.',body:'<p>The deck proposes Self-Understanding Activation Rate: the share of monthly active users who confirm or reflect on an insight. This measures engagement with interpretation; it does not by itself prove improved wellbeing.</p><ul><li><strong>Leading indicators:</strong> insight confirmation, reflection, and voluntary experiment participation.</li><li><strong>Outcome questions:</strong> does the experience support intentional use and sustained changes users value?</li><li><strong>Trust guardrails:</strong> opt-outs, negative reactions, inaccurate interpretations, and avoidance of the insight experience.</li><li><strong>Technical questions:</strong> consent, accessible Android usage signals, inference reliability, and data minimization.</li></ul><div class="case-callout">Next test: can a short reflection and voluntary experiment help users without adding guilt or cognitive load?</div><p>Behavior-change, retention, and revenue figures in the deck are ambitions or models. They are not achieved impact.</p>'}
]}
};
let lastCaseButton=null;let currentCase=null;const dialog=$('#case-dialog');
function setPanel(index){const c=cases[currentCase];$('#case-panel').innerHTML=`<h3>${c.panels[index].title}</h3>${c.panels[index].body}`;$$('.case-tabs button').forEach((b,i)=>{b.classList.toggle('active',i===index);b.setAttribute('aria-selected',String(i===index));b.tabIndex=i===index?0:-1});$('#case-panel').setAttribute('aria-labelledby','case-tab-'+index);window.dispatchEvent(new CustomEvent('portfolio:panel-change',{detail:{panel:'case-panel'}}));}
function openCase(key,button){currentCase=key;lastCaseButton=button;const c=cases[key];$('#case-content').innerHTML=`<div class="case-kicker">${c.kicker}</div><h2 id="case-title">${c.title}</h2><p class="case-deck">${c.intro}</p><div class="case-links"><a class="button primary" target="_blank" rel="noopener noreferrer" href="${c.prototype}">Try prototype ↗</a><a class="text-link" target="_blank" rel="noopener noreferrer" href="${c.deck}">Read original deck ↗</a></div><div class="case-tabs" role="tablist" aria-label="Case study chapters">${c.panels.map((p,i)=>`<button id="case-tab-${i}" role="tab" aria-controls="case-panel" aria-selected="${i===0}" tabindex="${i===0?0:-1}" data-panel="${i}">${p.label}</button>`).join('')}</div><div id="case-panel" class="case-panel" role="tabpanel" tabindex="0"></div><p class="case-evidence">${c.evidence}</p>`;setPanel(0);dialog.showModal();document.body.classList.add('modal-open');dialog.scrollTop=0;}
$$('[data-case]').forEach(b=>b.addEventListener('click',()=>openCase(b.dataset.case,b)));
$('#close-case').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>{document.body.classList.remove('modal-open');lastCaseButton?.focus()});dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}const t=e.target.closest('[data-panel]');if(t)setPanel(Number(t.dataset.panel));});
dialog.addEventListener('keydown',e=>{if(!e.target.matches('[role="tab"]'))return;let i=Number(e.target.dataset.panel);if(e.key==='ArrowRight')i=(i+1)%4;else if(e.key==='ArrowLeft')i=(i+3)%4;else if(e.key==='Home')i=0;else if(e.key==='End')i=3;else return;e.preventDefault();setPanel(i);$('#case-tab-'+i).focus()});
$$('[data-filter]').forEach(b=>b.addEventListener('click',()=>{const type=b.dataset.filter;$$('[data-filter]').forEach(x=>{const active=x===b;x.classList.toggle('active',active);x.setAttribute('aria-pressed',String(active))});$$('.lab-card').forEach(c=>c.hidden=type!=='all'&&c.dataset.type!==type);const n=$$('.lab-card').filter(c=>!c.hidden).length;$('.lab-count').textContent=n+' exploration'+(n===1?'':'s')}));
const signals=['Listen to the problem<br>behind the ticket.','Ask what changes<br>for the human.','Make the idea real.<br>Then question it again.'];$$('[data-signal]').forEach(b=>b.addEventListener('click',()=>{$('.signal-art').dataset.step=b.dataset.signal;$('#signal-text').innerHTML=signals[Number(b.dataset.signal)];$$('[data-signal]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});$('.art-top span:last-child').textContent='0'+(Number(b.dataset.signal)+1)+' / 03'}));
try{if(localStorage.getItem('sameer-theme-v2')==='light')document.body.classList.add('light')}catch{}function syncTheme(){const dark=!document.body.classList.contains('light');$('.theme-btn').setAttribute('aria-label','Switch to '+(dark?'light':'dark')+' theme');document.querySelector('meta[name="theme-color"]').content=dark?'#0a1018':'#f6f5f0'}syncTheme();$('.theme-btn').addEventListener('click',()=>{document.body.classList.toggle('light');syncTheme();try{localStorage.setItem('sameer-theme-v2',document.body.classList.contains('light')?'light':'dark')}catch{}});
let toastTimer;function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2800)}$('#copy-email').addEventListener('click',async()=>{try{await navigator.clipboard.writeText('sameerrosk358@gmail.com');toast('Email copied. Let’s talk.')}catch{toast('Email: sameerrosk358@gmail.com')}});
$('#year').textContent=new Date().getFullYear();let scrollPending=false;addEventListener('scroll',()=>{if(scrollPending)return;scrollPending=true;requestAnimationFrame(()=>{const max=document.documentElement.scrollHeight-innerHeight;$('.scroll-progress').style.width=(max>0?scrollY/max*100:0)+'%';scrollPending=false})},{passive:true});

