function wireArrowTabs(selector,key,render){$$(selector).forEach(b=>b.addEventListener('keydown',e=>{let i=Number(b.dataset[key]);if(['ArrowRight','ArrowDown'].includes(e.key))i=(i+1)%4;else if(['ArrowLeft','ArrowUp'].includes(e.key))i=(i+3)%4;else if(e.key==='Home')i=0;else if(e.key==='End')i=3;else return;e.preventDefault();render(i);$$(selector)[i].focus()}));}
